describe("Defect check: The 'Your Name' input field is not visible in the form; only 'Your Email' and 'Your Phone' fields are present in the top row.", () => {
  it('validates the live application against the reported discrepancy', () => {
    cy.visit("http://localhost:5174/");
    cy.get('body', { timeout: 10000 }).should('be.visible');
    const expectedKeyword = "your";
    const normalize = (value) => (value || '').toString().replace(/\s+/g, ' ').trim().toLowerCase();
    const collectLiveUiTokens = (doc) => {
      const tokens = [];
      const seen = new Set();
      const addToken = (value) => {
        const norm = normalize(value);
        if (!norm || norm.length < 2 || seen.has(norm)) {
          return;
        }
        seen.add(norm);
        tokens.push(norm);
      };

      const allNodes = Array.from(doc.querySelectorAll('*'));
      allNodes.forEach((el) => {
        addToken(el.textContent);
        addToken(el.getAttribute('aria-label'));
        addToken(el.getAttribute('data-testid'));
        addToken(el.getAttribute('id'));
        addToken(el.getAttribute('name'));
        addToken(el.getAttribute('title'));
        addToken(el.getAttribute('alt'));
        addToken(el.getAttribute('placeholder'));

        if (el.matches && el.matches('input, textarea, select')) {
          addToken(el.value);
          const fieldId = el.getAttribute('id');
          if (fieldId) {
            doc.querySelectorAll(`label[for=\"${fieldId}\"]`).forEach((label) => addToken(label.textContent));
          }
          const parentLabel = el.closest('label');
          if (parentLabel) {
            addToken(parentLabel.textContent);
          }
        }
      });

      return {
        haystack: tokens.join('\n'),
        tokenCount: tokens.length,
        elementCount: allNodes.length,
      };
    };

    cy.document({ timeout: 10000 }).then((doc) => {
      const expected = normalize(expectedKeyword);
      const inventory = collectLiveUiTokens(doc);
      const found = inventory.haystack.includes(expected);
      expect(found, `Expected keyword: ${expected} (scanned ${inventory.elementCount} elements / ${inventory.tokenCount} tokens)`).to.eq(true);
    });
  });
});

